window.__votdWeek && window.__votdWeek({"week":"2027-12-06","reading":"Revelation 6–14","days":[{"d":"2027-12-06","ref":"Revelation 6:10","b":"Revelation","c":6,"v":10,"he":"וַיִּזְעֲקוּ בְּקוֹל גָּדוֹל וַיֹּאמְרוּ אֲדֹנָי הַקָּדוֹשׁ וְהָאֲמִתִּי עַד־מָתַי לֹא תִשְׁפֹּט וְלֹא־תִקּוֹם אֶת־דָּמֵינוּ מִיֹּשְׁבֵי הָאָרֶץ׃","en":"And they cried with a loud voice, saying, How long, O Lord, holy and true, dost thou not judge and avenge our blood on them that dwell on the earth?"},{"d":"2027-12-07","ref":"Revelation 6:12","b":"Revelation","c":6,"v":12,"he":"וָאֵרֶא בְּפִתְחוֹ אֶת־הַחוֹתָם הַשִּׁשִּׁי וְהִנֵּה רַעַשׁ גָּדוֹל וַיִּקְדַּר הַשֶּׁמֶשׁ כְּשַׂק שֵׂעָר וְהַיָּרֵחַ נֶהְפַּךְ לְדָם׃","en":"And I beheld when he had opened the sixth seal, and, lo, there was a great earthquake; and the sun became black as sackcloth of hair, and the moon became as blood;"},{"d":"2027-12-08","ref":"Revelation 7:14","b":"Revelation","c":7,"v":14,"he":"וָאֹמַר אֵלָיו אֲדֹנִי אַתָּה יָדָעְתָּ וַיֹּאמֶר אֵלַי אֵלֶּה הֵם הַבָּאִים מִן־הַצָּרָה הַגְּדוֹלָה וַיְכַבְּסוּ אֶת־שִׂמְלֹתָם וַיַּלְבִּינוּם בְּדַם הַשֶׂה׃","en":"And I said unto him, Sir, thou knowest. And he said to me, These are they which came out of great tribulation, and have washed their robes, and made them white in the blood of the Lamb."},{"d":"2027-12-09","ref":"Revelation 11:15","b":"Revelation","c":11,"v":15,"he":"וְהַמַּלְאָךְ הַשְּׁבִיעִי תָּקַע בַּשּׁוֹפָר וַיְהִי קֹלוֹת גְּדוֹלִים בַּשָּׁמַיִם וַיֹּאמְרוּ הִנֵּה מַמְלֶכֶת הָעוֹלָם הָיְתָה לַאֲדֹנֵינוּ וְלִמְשִׁיחוֹ וְהוּא יִמְלֹךְ לְעוֹלְמֵי עוֹלָמִים׃","en":"And the seventh angel sounded; and there were great voices in heaven, saying, The kingdoms of this world are become the kingdoms of our Lord, and of his Christ; and he shall reign for ever and ever."},{"d":"2027-12-10","ref":"Revelation 12:9","b":"Revelation","c":12,"v":9,"he":"וַיֻּשְׁלַךְ הַתַּנִּין הַגָּדוֹל הַנָּחָשׁ הַקַּדְמוֹנִי אֲשֶׁר־נִקְרָא שְׁמוֹ מַלְשִׁין וְשָׂטָן הַמַּדִּיחַ תֵּבֵל כֻּלָּהּ הוּא הֻשְׁלַךְ אָרְצָה וּמַלְאָכָיו עִמּוֹ הֻשְׁלָכוּ׃","en":"And the great dragon was cast out, that old serpent, called the Devil, and Satan, which deceiveth the whole world: he was cast out into the earth, and his angels were cast out with him."},{"d":"2027-12-11","ref":"Revelation 14:1","b":"Revelation","c":14,"v":1,"he":"וָאֵרֶא וְהִנֵּה־שֶׂה עֹמֵד עַל־הַר צִיּוֹן וְעִמּוֹ מְאַת אֶלֶף וְאַרְבָּעִים וְאַרְבָּעָה אֲלָפִים וּשְׁמוֹ וְשֵׁם אָבִיו כָּתוּב עַל־מִצְחוֹתָם׃","en":"And I looked, and, lo, a Lamb stood on the mount Sion, and with him an hundred forty and four thousand, having his Father's name written in their foreheads."},{"d":"2027-12-12","ref":"Revelation 14:13","b":"Revelation","c":14,"v":13,"he":"וָאֶשְׁמַע קוֹל מִן־הַשָּׁמָיִם מְדַבֵּר אֵלַי כְּתֹב אַשְׁרֵי הַמֵּתִים אֲשֶׁר־יָמוּתוּ בָּאָדוֹן מֵעָתָּה אׇמְנָם כֵּן אָמַר הָרוּחַ לְמַעַן יָנוּחוּ מֵעֲמָלָם כִּי מַעֲשֵׂיהֶם הֹלְכִים אַחֲרֵיהֶם׃","en":"And I heard a voice from heaven saying unto me, Write, Blessed are the dead which die in the Lord from henceforth: Yea, saith the Spirit, that they may rest from their labours; and their works do follow them."}]});
